attempts.script:
# Estimate parasitics using global routing
estimate_parasitics -global_route

# Report clock skew for setup checks
# We output to a temporary file first to control precision
report_clock_skew -setup core_clock -file outputs/ct03_clock_skew.rpt.tmp

# Read the temporary report
set tmp_file "outputs/ct03_clock_skew.rpt.tmp"
set content [read $tmp_file]
close $tmp_file

# Find the line containing "Worst skew"
# The format is usually "Worst skew: <value> ns"
# We need to replace the value with a 4-digit decimal version
set new_content [regsub -all {\nWorst skew: [0-9]+\.[0-9]+ ns} $content "\nWorst skew: [format %.4f [expr [regexp -all -inline {\d+\.\d+} $content] ? [lindex [regexp -all -inline {\d+\.\d+} $content] 0] : 0.0000] ns"] $content]

# This regex approach is tricky. Let's do it more carefully.
# We can use a loop to find the line and replace it.
set lines [split $content "\n"]
set new_lines [list]
set found 0
foreach line $lines {
    if {[string match "*Worst skew:*" $line]} {
        # Extract the value
        if {[regexp {Worst skew: ([0-9]+\.[0-9]+) ns} $line match val]} {
            set formatted_val [format %.4f $val]
            lappend new_lines "Worst skew: $formatted_val ns"
            set found 1
        } else {
            lappend new_lines $line
        }
    } else {
        lappend new_lines $line
    }
}

# If we didn't find it, just keep the original
if {!$found} {
    set new_content $content
} else {
    set new_content [join $new_lines "\n"]
}

# Write the final report
set fp [open outputs/ct03_clock_skew.rpt w]
puts -nonewline $fp $new_content
close $fp

# Clean up temp file if it exists
if {[file exists outputs/ct03_clock_skew.rpt.tmp]} {
    file delete outputs/ct03_clock_skew.rpt.tmp
}

set total_cell_area 0
foreach cell [get_cells -hierarchical *] {
    # Check if it is a standard cell
    if {[dbIsStandardCell $cell]} {
        set cell_area [dbGet $cell.area]
        set total_cell_area [expr {$total_cell_area + $cell_area}]
    }
}

# Ensure output directory exists
file mkdir outputs

# Open output file
set outfile [open outputs/io_ports.txt w]

# Get all top-level ports
set ports [get_ports]

foreach port $ports {
    set port_name [get_property name $port]
    set direction [get_property direction $port]

    # Check if it's a bus
    if {[regexp {^(.+)\\[(\\d+):(\\d+)\\]$} $port_name match base_name msb lsb]} {
        # It is a bus
        # Determine step direction
        if {$msb > $lsb} {
            set step -1
        } else {
            set step 1
        }

        # Iterate through bits
        for {set i $msb} {$i != [expr {$lsb + $step}]} {incr i $step} {
            puts $outfile "$base_name[$i] $direction"
        }
    } else {
        # It is a single-bit port
        puts $outfile "$port_name $direction"
    }
}

close $outfile

# Initialize the dictionary to count cell types
set cell_counts [dict create]
set total_count 0

# Get all instances in the design
set all_instances [get_cells -hierarchical *]

foreach inst $all_instances {
    # Get the reference cell name (library cell type)
    set ref_name [get_property REF_NAME $inst]

    # Skip if ref_name is empty (should not happen for valid instances)
    if { [string equal $ref_name ""] } {
        continue
    }

    # Exclude physical-only cells based on naming patterns
    # Tap/Endcap cells
    if { [string match -nocase "TAPCELL*" $ref_name] } {
        continue
    }

    # Filler cells
    if { [string match -nocase "FILLCELL*" $ref_name] } {
        continue
    }

    # Increment count for this cell type
    if { [dict exists $cell_counts $ref_name] } {
        set current_count [dict get $cell_counts $ref_name]
        dict set cell_counts $ref_name [expr {$current_count + 1}]
    } else {
        dict set cell_counts $ref_name 1
    }

    # Increment total count
    incr total_count
}

# Create the output directory if it doesn't exist
if { [file exists outputs] == 0 } {
    file mkdir outputs
}

# Open the output file
set output_file "outputs/cell_usage.txt"
set fp [open $output_file w]

# Write each cell type and its count
foreach cell_type [lsort [dict keys $cell_counts]] {
    set count [dict get $cell_counts $cell_type]
    puts $fp "$cell_type $count"
}

# Write the total count
puts $fp "total $total_count"

# Close the file
close $fp

# Create the outputs directory if it doesn't exist
if {[file exists outputs] == 0} {
    file mkdir outputs
}

# --- Part 1: Analyze Flip-Flop Types ---

# Get all cells that are flip-flops. 
# In Nangate45, DFFs are typically named DFF* (e.g., DFFR, DFFS, DFFX, etc.)
# We get all cells and filter by name prefix or type. 
# get_cells -hierarchy -filter "name =~ DFF*" gets all instances.
set dff_instances [get_cells -hierarchy -filter "name =~ DFF*"]

# Create a dictionary to count types
set type_counts [dict create]
set total_flops 0

foreach inst $dff_instances {
    # Get the cell type of the instance
    set cell_type [get_property $inst TYPE]

    # Update the count
    if {[dict exists $type_counts $cell_type]} {
        set current_count [dict get $type_counts $cell_type]
        dict set type_counts $cell_type [expr {$current_count + 1}]
    } else {
        dict set type_counts $cell_type 1
    }

    incr total_flops
}

# Write flop_types.txt
set f [open outputs/flop_types.txt w]
foreach type [lsort [dict keys $type_counts]] {
    set count [dict get $type_counts $type]
    puts $f "$type $count"
}
puts $f "total $total_flops"
close $f

# --- Part 2: Analyze Flip-Flop Clock Drivers ---

# Dictionary to store driver instance names and their counts
set driver_counts [dict create]

foreach inst $dff_instances {
    # Identify the clock pin. In Nangate45, it is typically 'CK'.
    # Some might be 'CLK'. We'll try 'CK' first, then 'CLK'.
    set clk_pin ""
    if {[get_pins -of_objects $inst -filter "name == CK"] != ""} {
        set clk_pin [get_pins -of_objects $inst -filter "name == CK"]
    } elseif {[get_pins -of_objects $inst -filter "name == CLK"] != ""} {
        set clk_pin [get_pins -of_objects $inst -filter "name == CLK"]
    } else {
        # If no standard clock pin found, skip or handle error. 
        # For this design, we assume standard DFFs.
        continue
    }

    # Get the net connected to the clock pin
    set clk_net [get_property $clk_pin CONNECTED_NET]

    # Get the source pins of the net (driving cells)
    # A net might have multiple drivers, but usually one for clock.
    # We want the instance name of the driver.
    set driver_pins [get_pins -of_objects $clk_net -direction OUT]

    foreach driver_pin $driver_pins {
        set driver_cell [get_property $driver_pin CELL]
        set driver_inst_name [get_property $driver_pin INSTANCE]

        # Update the count for this driver instance
        if {[dict exists $driver_counts $driver_inst_name]} {
            set current_count [dict get $driver_counts $driver_inst_name]
            dict set driver_counts $driver_inst_name [expr {$current_count + 1}]
        } else {
            dict set driver_counts $driver_inst_name 1
        }
    }
}

# Write flop_clock_drivers.txt
set f [open outputs/flop_clock_drivers.txt w]
foreach driver [lsort [dict keys $driver_counts]] {
    set count [dict get $driver_counts $driver]
    puts $f "$driver $count"
}
close $f

# Get the current HPWL
proc get_hpwl {} {
    set hpwl 0
    foreach net [get_nets -hierarchical -except [get_nets -hierarchical -filter "name =~ VDD* || name =~ GND* || name =~ *clk*"]] {
        set pins [get_pins -hierarchical -of_objects $net]
        if {[llength $pins] < 2} {
            continue
        }
        set min_x 1e9
        set max_x -1e9
        set min_y 1e9
        set max_y -1e9
        foreach pin $pins {
            # Get the location of the pin
            # The pin location is relative to the cell origin, but we need the global location
            # We can get the cell location and add the pin offset
            set cell [get_cells -hierarchical -of_objects $pin]
            set cell_loc [get_cell_location $cell]
            set pin_offset [get_pin_offset $pin]
            set x [expr {[lindex $cell_loc 0] + [lindex $pin_offset 0]}]
            set y [expr {[lindex $cell_loc 1] + [lindex $pin_offset 1]}]
            if {$x < $min_x} { set min_x $x }
            if {$x > $max_x} { set max_x $x }
            if {$y < $min_y} { set min_y $y }
            if {$y > $max_y} { set max_y $y }
        }
        set hpwl [expr {$hpwl + ($max_x - $min_x) + ($max_y - $min_y)}]
    }
    return $hpwl
}

# Get initial HPWL
set initial_hpwl [get_hpwl]
puts "Initial HPWL: $initial_hpwl"

# Get all standard cells
set cells [get_cells -hierarchical -filter "is_standard_cell == 1"]
set num_cells [llength $cells]

# Mapping of orientations to their mirror images
# N <-> FN, S <-> FS, R90 <-> FR90, R270 <-> FR270
proc get_mirror_orientation {orient} {
    switch $orient {
        N { return FN }
        FN { return N }
        S { return FS }
        FS { return S }
        R90 { return FR90 }
        FR90 { return R90 }
        R270 { return FR270 }
        FR270 { return R270 }
        default { return "" }
    }
}

set improved 1
set iter 0
set max_iter 10

while {$improved && $iter < $max_iter} {
    set improved 0
    incr iter
    puts "Iteration $iter"

    # Shuffle cells to avoid bias
    set shuffled_cells [lsort -random $cells]

    foreach cell $shuffled_cells {
        set current_orient [get_cell_orientation $cell]
        set mirror_orient [get_mirror_orientation $current_orient]

        # If no mirror orientation (e.g., symmetric or not applicable), skip
        if {$mirror_orient == ""} {
            continue
        }

        # Try to move the cell to the mirror orientation
        # We need to save the current HPWL to compare
        # But calculating HPWL for every trial is slow.
        # Instead, we can estimate the HPWL change by looking at the pins of the nets connected to this cell.

        # Get nets connected to this cell
        set cell_pins [get_pins -hierarchical -of_objects $cell]
        set nets [get_nets -hierarchical -of_objects $cell_pins]

        # Calculate current HPWL contribution of these nets? 
        # This is complex because HPWL is global.
        # Let's just calculate the total HPWL for the trial.

        # Move cell
        move_cell $cell -orientation $mirror_orient

        # Check legality? The move_cell command should ensure legality if the orientation is valid.
        # But let's assume it's legal.

        set trial_hpwl [get_hpwl]

        if {$trial_hpwl < $initial_hpwl} {
            # Keep the new orientation
            set initial_hpwl $trial_hpwl
            set improved 1
            # puts "Improved HPWL to $initial_hpwl by flipping $cell from $current_orient to $mirror_orient"
        } else {
            # Revert the orientation
            move_cell $cell -orientation $current_orient
        }
    }
}

# Final HPWL
set final_hpwl [get_hpwl]
set reduction [expr {($initial_hpwl - $final_hpwl) / $initial_hpwl * 100}]
puts "Final HPWL: $final_hpwl"
puts "Reduction: $reduction %"

# Write outputs
if {$reduction >= 1.0} {
    puts "HPWL reduction achieved: $reduction %"
} else {
    puts "HPWL reduction not achieved: $reduction %"
}

# Write the final placement
write_lef outputs/final_placement.lef
write_def outputs/final_placement.def

# Ensure output directory exists
file mkdir outputs

# Extract parasitics from the current global routing result.
# This command estimates wire RC based on the global routing guides stored in the database.
# It does not re-run global routing.
extract_parasitics

# Report timing to get setup slack information.
# We use report_timing -summary to get a concise summary including WNS and TNS.
# The output is captured to a variable.
set timing_summary [report_timing -summary]

# Parse the WNS and TNS from the timing summary.
# The format typically looks like:
# WNS: -0.1234 ns
# TNS: -1.2345 ns
# We use regexp to extract the values.

set wns_value ""
set tns_value ""

# Extract WNS
if {[regexp {WNS:\s+(-?[0-9]+\.[0-9]+) ns} $timing_summary match wns_value]} {
    # Format to 4 decimal places
    set wns_formatted [format "%.4f" $wns_value]
} else {
    # Fallback if format differs slightly, e.g., no 'ns' or different spacing
    if {[regexp {WNS:\s+(-?[0-9]+\.?[0-9]*)} $timing_summary match wns_value]} {
        set wns_formatted [format "%.4f" $wns_value]
    } else {
        set wns_formatted "0.0000"
    }
}

# Extract TNS
if {[regexp {TNS:\s+(-?[0-9]+\.[0-9]+) ns} $timing_summary match tns_value]} {
    # Format to 4 decimal places
    set tns_formatted [format "%.4f" $tns_value]
} else {
    if {[regexp {TNS:\s+(-?[0-9]+\.?[0-9]*)} $timing_summary match tns_value]} {
        set tns_formatted [format "%.4f" $tns_value]
    } else {
        set tns_formatted "0.0000"
    }
}

# Write the result to the output file
set output_file "outputs/wns_tns.txt"
set fid [open $output_file w]
puts $fid "WNS=$wns_formatted TNS=$tns_formatted"
close $fid

# Define a procedure to extract bit index for sorting
proc get_bit_index {port_name} {
    if {[regexp {req_msg\[(\d+)\]} $port_name -> bit]} {
        return $bit
    }
    return -1
}

# Get all IO ports
set all_ports [get_ports -hierarchical *]

# Separate req_msg pins and others
set req_ports [list]
set other_ports [list]

foreach port $all_ports {
    if {[string match "*req_msg*" $port]} {
        lappend req_ports $port
    } else {
        lappend other_ports $port
    }
}

# Sort req_ports by bit index
set sorted_req_ports [lsort -command {
    proc sort_bits {a b} {
        set bit_a [get_bit_index $a]
        set bit_b [get_bit_index $b]
        return [expr {$bit_a - $bit_b}]
    }
    sort_bits $a $b
} $req_ports]

# Die dimensions
set die_x_max 100.13
set die_y_max 100.8

# Prepare arguments for place_pins
set args [list]

# Place req_msg pins on bottom edge (Y=0) with Metal 2
set num_req [llength $sorted_req_ports]
if {$num_req > 0} {
    for {set i 0} {$i < $num_req} {incr i} {
        set pin [lindex $sorted_req_ports $i]
        # Calculate X coordinate: evenly spaced from 0 to 100.13
        set x [expr {$i * $die_x_max / ($num_req - 1)}]
        lappend args -pin $pin -location $x 0 -layer metal2
    }
}

# Place other pins on top edge (Y=100.8) with Metal 2
set num_other [llength $other_ports]
if {$num_other > 0} {
    for {set i 0} {$i < $num_other} {incr i} {
        set pin [lindex $other_ports $i]
        # Calculate X coordinate: evenly spaced from 0 to 100.13
        set x [expr {$i * $die_x_max / ($num_other - 1)}]
        lappend args -pin $pin -location $x $die_y_max -layer metal2
    }
}

# Execute place_pins
if {[llength $args] > 0} {
    eval place_pins $args
}

# Create the output directory if it doesn't exist
file mkdir outputs

# Open the output file
set output_file [open outputs/io_ports.txt w]

# Get all ports of the top-level design
set ports [get_ports -of_objects [get_designs gcd]]

# Iterate through each port and write its name and direction
foreach port $ports {
    set port_name [get_name $port]
    set direction [get_property DIRECTION $port]

    # Check if the port is a bus (has bits)
    set bits [get_property BITS $port]

    if {$bits > 1} {
        # For multi-bit ports, list each bit individually
        for {set i 0} {$i < $bits} {incr i} {
            puts $output_file "$port_name[$i] $direction"
        }
    } else {
        # For single-bit ports, list the port name directly
        puts $output_file "$port_name $direction"
    }
}

# Close the output file
close $output_file

# Open the output file
set outfile [open outputs/cell_usage.txt w]

# Get all instances in the design
set instances [get_instances]

# Associative array to store counts
set cell_counts {}
set total_count 0

# Iterate through each instance
foreach inst $instances {
    # Get the cell name associated with the instance
    set cell_name [get_property $inst CELL]

    # Skip empty cell names (if any)
    if {$cell_name eq ""} {
        continue
    }

    # Check if the cell is a tap/endcap or filler cell
    # Tap cells: TAPCELL*
    # Filler cells: FILLCELL*
    if {[string match "TAPCELL*" $cell_name] || [string match "FILLCELL*" $cell_name]} {
        continue
    }

    # Increment count for this cell type
    if {[info exists cell_counts($cell_name)]} {
        set cell_counts($cell_name) [expr {$cell_counts($cell_name) + 1}]
    } else {
        set cell_counts($cell_name) 1
    }

    # Increment total count
    set total_count [expr {$total_count + 1}]
}

# Write each cell type and its count
foreach cell_name [lsort [array names cell_counts]] {
    puts $outfile "$cell_name $cell_counts($cell_name)"
}

# Write the total count
puts $outfile "total $total_count"

# Close the output file
close $outfile

# Identify clock net
set clock_nets [list]
foreach clk [get_clocks] {
    set root_pins [get_pins -of_objects $clk]
    foreach rp $root_pins {
        set nets [get_nets -of_objects $rp]
        foreach n $nets {
            lappend clock_nets $n
        }
    }
}

# Identify power/ground nets
set pg_nets [get_nets -filter "is_power || is_ground"]

# Build a set of excluded nets
set excluded_nets [concat $clock_nets $pg_nets]
# Remove duplicates
set excluded_nets [lsort -unique $excluded_nets]

# Build mapping of nets to top-level output ports
set port_map [dict create]
foreach port [get_ports -filter "is_output"] {
    set nets [get_nets -of_objects $port]
    foreach n $nets {
        # A port might be connected to multiple nets? Unlikely.
        # If a net is already in the map, append?
        if {[dict exists $port_map $n]} {
            set existing [dict get $port_map $n]
            lappend existing $port
            dict set port_map $n $existing
        } else {
            dict set port_map $n $port
        }
    }
}

# Iterate over all nets and calculate fanout
set fanout_list [list]
foreach net [get_nets -hierarchy] {
    # Check if excluded
    set is_excluded 0
    foreach en $excluded_nets {
        if {$net eq $en} {
            set is_excluded 1
            break
        }
    }
    if {$is_excluded} {
        continue
    }

    # Count input pins
    set pins [get_pins -of_objects $net]
    set input_pin_count 0
    foreach pin $pins {
        if {[get_property $pin is_input]} {
            incr input_pin_count
        }
    }

    # Add top-level output ports
    set port_count 0
    if {[dict exists $port_map $net]} {
        set ports [dict get $port_map $net]
        set port_count [llength $ports]
    }

    set total_fanout [expr {$input_pin_count + $port_count}]

    # We only care about nets with fanout > 0? The task asks for highest fanout.
    # If a net has 0 fanout, it's likely a net tied to nothing or just a driver?
    # We include all nets.
    lappend fanout_list "$net $total_fanout"
}

# Sort by fanout descending
# Format: "net_name fanout"
# We need to sort numerically by the second field.
set sorted_list [lsort -decreasing -command {
    proc compare_fanout {a b} {
        set fanout_a [lindex [split $a] end]
        set fanout_b [lindex [split $b] end]
        if {$fanout_a > $fanout_b} {
            return -1
        } elseif {$fanout_a < $fanout_b} {
            return 1
        } else {
            return 0
        }
    }
    compare_fanout $a $b
} $fanout_list]

# Take top 5
set top5 [lrange $sorted_list 0 4]

# Write to file
set fid [open "outputs/high_fanout_nets.txt" w]
foreach line $top5 {
    puts $fid $line
}
close $fid

# 1. Get all instances
set all_insts [get_instances -hierarchical *]

# 2. Identify FFs
# Define FF prefixes for Nangate45
set ff_prefixes {"DFF" "JKFF" "TFF" "SRFF" "DFFE" "JKFFE" "TFFE" "SRFFE" "DFFS" "DFFR" "DFFN" "DFFP" "DFFH"} 
# Note: This is a heuristic. A more robust way is to check if the cell has a CLK pin and is not a latch.
# But checking LIB for 'clock' property on pins is hard in Tcl.
# Let's use the prefix method as it's standard for Nangate45.

set ff_cell_types {}
set ff_instances {}

foreach inst $all_insts {
    set cell_name [get_property [get_cells $inst] leaf_cell_name]
    # Check if cell name starts with any FF prefix
    set is_ff 0
    foreach prefix $ff_prefixes {
        if {[string match "${prefix}*" $cell_name]} {
            set is_ff 1
            break
        }
    }
    # Also check for other common FF names if they don't match prefixes? 
    # Nangate45 is pretty consistent.

    if {$is_ff} {
        lappend ff_instances $inst
        lappend ff_cell_types $cell_name
    }
}

# 3. Count FFs by type
set type_counts {}
foreach ctype $ff_cell_types {
    if {[info exists type_counts($ctype)]} {
        incr type_counts($ctype)
    } else {
        set type_counts($ctype) 1
    }
}

set total_ffs [llength $ff_instances]

# 4. Write flop_types.txt
set f1 [open "outputs/flop_types.txt" w]
foreach ctype [lsort [array names type_counts]] {
    puts $f1 "$ctype $type_counts($ctype)"
}
puts $f1 "total $total_ffs"
close $f1

# 5. Identify Clock Drivers
# Map: driver_instance -> count of FFs driven
set driver_counts {}

foreach inst $ff_instances {
    # Get the cell
    set cell [get_cells $inst]
    # Find the clock pin. Usually CLK or CK.
    # Nangate45 FFs typically have pin CLK.
    set clk_pin [get_pins -of_objects $cell -filter "direction == input && name == CLK"]
    if {$clk_pin eq ""} {
        # Try CK
        set clk_pin [get_pins -of_objects $cell -filter "direction == input && name == CK"]
    }
    if {$clk_pin eq ""} {
        # Skip if no clock pin found
        continue
    }

    # Get the net driving this pin
    set clk_net [get_nets -of_objects $clk_pin]
    if {$clk_net eq ""} {
        continue
    }

    # Get the driving pins of this net
    # We want instances whose output pin drives this net
    set driver_pins [get_pins -of_objects [get_nets $clk_net] -filter "direction == output"]

    foreach dpin $driver_pins {
        set driver_inst [get_property [get_cells $dpin] parent]
        if {[info exists driver_counts($driver_inst)]} {
            incr driver_counts($driver_inst)
        } else {
            set driver_counts($driver_inst) 1
        }
    }
}

# 6. Write flop_clock_drivers.txt
set f2 [open "outputs/flop_clock_drivers.txt" w]
foreach driver [lsort [array names driver_counts]] {
    puts $f2 "$driver $driver_counts($driver)"
}
close $f2

set design [current_design]
set ports [get_ports -direction input]
set clk_port [get_ports clk]
# Filter out clk
set input_ports [lsearch -all -inline -not -glob $ports "clk"]
# Wait, lsearch might not work like that if ports are objects.
# Better:
foreach port $ports {
    set port_name [get_property $port NAME]
    if {$port_name ne "clk"} {
        # Process port
    }
}

# Create outputs directory if not exists (assuming it exists or creating it)
# The task says "Write outputs/...". We assume the directory exists or we can create it?
# Tcl doesn't have mkdir? Yes, `file mkdir outputs`

file mkdir outputs

# --- BEFORE FIX ---

# Start logging
