puts "Initial HPWL: $initial_hpwl"

# 2. Identify candidate cells
# Exclude IOs, Macros, Taps, Fillers
# Standard cells in Nangate45 are typically in the 'stdcell' hierarchy or have specific types
# We can filter by is_std_cell property if available, or by excluding known types.
# In OpenROAD, 'is_std_cell' is a common property.
set all_cells [get_cells -hierarchical]
set candidate_cells {}

foreach cell $all_cells {
    # Skip if not a standard cell
    if {[catch {get_property is_std_cell $cell} is_std] || $is_std != 1} {
        continue
    }

    # Skip IO cells
    if {[catch {get_property IS_IO $cell} is_io] || $is_io == 1} {
        continue
    }

    # Skip macros (if any are marked as std_cell erroneously, but usually macros are not std_cell)
    # Skip Taps and Fillers by name pattern if necessary, but is_std_cell usually covers logic cells
    # Let's also exclude TAPCELL and FILLCELL explicitly just in case
    set cell_name [get_property NAME $cell]
    if {[string match "TAPCELL*" $cell_name] || [string match "FILLCELL*" $cell_name]} {
        continue
    }

    lappend candidate_cells $cell
}

puts "Number of candidate cells: [llength $candidate_cells]"

# 3. Iterative Mirroring
set current_hpwl $initial_hpwl
set max_passes 10
set pass 0
set improved true

while {$improved && $pass < $max_passes} {
    incr pass
    set improved false
    puts "Pass $pass..."

    # We need to try flipping each cell. 
    # To avoid re-evaluating the entire netlist HPWL for every single cell in a single pass (which is O(N^2)),
    # we can try a greedy approach: flip if it improves, keep it, then move to next.
    # However, order matters. A better approach for small N is to try all, find the best flip, apply it, and repeat.
    # But "best flip" might be one of many. Let's do a "best single flip per pass" strategy.

    set best_cell ""
    set best_hpwl $current_hpwl

    foreach cell $candidate_cells {
        set current_orient [get_property orientation $cell]

        # Determine mirrored orientation
        set new_orient ""
        if {$current_orient == "N"} {
            set new_orient "S"
        } elseif {$current_orient == "S"} {
            set new_orient "N"
        } elseif {$current_orient == "W"} {
            set new_orient "E"
        } elseif {$current_orient == "E"} {
            set new_orient "W"
        } else {
            # Unsupported or unknown orientation, skip
            continue
        }

        # Check if new orientation is valid for this cell
        # In OpenROAD, we can check if the cell can be placed in this orientation.
        # A simple check is to see if the cell is compatible with the row orientation.
        # Most Nangate45 cells support N and S.

        # Temporarily set orientation
        set_property orientation $new_orient $cell

        # Check legality. 'check_placement' is global and slow.
        # Instead, we can rely on the fact that N<->S is almost always legal for standard cells in horizontal rows.
        # If we want to be safe, we can check if the cell's bounding box overlaps others, but that's complex.
        # Let's assume N/S flip is legal for all std cells in this context.

        # Calculate HPWL
        # report_wirelength is the only way to get accurate HPWL in OpenROAD 2.0
        set hpwl_data [report_wirelength -format hpwl]
        set hpwl [expr [lindex $hpwl_data 0]]

        if {$hpwl < $best_hpwl} {
            set best_hpwl $hpwl
            set best_cell $cell
        } else {
            # Revert if not better
            set_property orientation $current_orient $cell
        }
    }

    # If we found a better cell, apply the change
    if {$best_cell != ""} {
        set current_hpwl $best_hpwl
        # The cell is already set to new_orient in the loop if it was the best, 
        # but we reverted others. We need to ensure best_cell stays flipped.
        # In the loop, if best_cell was the best, we did NOT revert it.
        # So it is already in the new orientation.
        set improved true
        puts "Pass $pass: Flipped [get_property NAME $best_cell] to [get_property orientation $best_cell]. New HPWL: $current_hpwl"
    } else {
        set improved false
        puts "Pass $pass: No improvement found."
    }
}

