# Let's split by "Path: " and then prepend "Path: " back to each chunk (except the first if it's garbage).

# Actually, a safer split is to look for lines starting with "Path:"
set path_blocks [regexp -all -inline -line {^Path:.*} $worst_text]
# This gives a list of lines starting with "Path:".
# But a path block might span multiple lines.
# Let's split the whole `worst_text` by these markers.

set full_text $worst_text
set paths_to_analyze {}
set current_block ""

# Split by lines starting with "Path:"
set lines [split $full_text "\n"]
set in_block 0
set block_lines {}

foreach line $lines {
    if {[regexp {^Path:} $line]} {
        if {$in_block && [llength $block_lines] > 0} {
            lappend paths_to_analyze [join $block_lines "\n"]
        }
        set block_lines [list $line]
        set in_block 1
    } else {
        if {$in_block} {
            lappend block_lines $line
        }
    }
}
if {$in_block && [llength $block_lines] > 0} {
    lappend paths_to_analyze [join $block_lines "\n"]
}

# Now analyze each block to find Endpoint and Slack
set analyzed_paths {}
foreach block $paths_to_analyze {
    set block_lines [split $block "\n"]
    set endpoint ""
    set slack ""

    foreach line $block_lines {
        if {[regexp {^Endpoint:\s+(.*)} $line match ep]} {
            set endpoint $ep
        }
        if {[regexp {^Slack:\s+(-?[0-9.]+)} $line match sl]} {
            set slack [expr double($sl)]
        }
    }

    if {$endpoint ne "" && $slack ne ""} {
        lappend analyzed_paths [list $endpoint $slack $block]
    }
}

# Sort by slack (ascending, most negative first)
set sorted_paths [lsort -real -increasing [lmap p $analyzed_paths {lindex $p 1}]]
# Wait, lsort -real works on the list elements if they are numbers.
# I need to sort the `analyzed_paths` list based on the slack (index 1).
set sorted_paths [lsort -real -increasing -index 1 $analyzed_paths]

# Select top 3 unique endpoints
set selected_paths {}
set seen_endpoints {}

foreach p $sorted_paths {
    set ep [lindex $p 0]
    if {[lsearch $seen_endpoints $ep] == -1} {
        lappend seen_endpoints $ep
        lappend selected_paths $p
        if {[llength $selected_paths] == 3} {
            break
        }
    }
}

# If we have fewer than 3 unique endpoints, we just take what we have.
# Write the report
set out_file [open outputs/hold_paths.rpt w]

puts $out_file "Post-CTS Hold Timing Report - 3 Worst Paths"
puts $out_file "=========================================="

foreach p $selected_paths {
    set block [lindex $p 2]
    puts $out_file $block
    puts $out_file ""
}

close $out_file

# Ensure outputs directory exists
file mkdir outputs

# 1. Extract parasitics
extract_rc -rules platform/Nangate45.rcx_rules -spef outputs/gcd.spef

# 2. Run setup timing analysis (max delay)
# Redirect output to a file for parsing
redirect outputs/setup_timing.txt {
    report_timing -delay max -endpoints 100000
}

# 3. Run hold timing analysis (min delay)
redirect outputs/hold_timing.txt {
    report_timing -delay min -endpoints 100000
}

# 4. Parse setup timing
set setup_slacks [list]
set setup_violating_count 0
set total_neg_setup_slack 0.0

set file [open outputs/setup_timing.txt r]
while {[gets $file line] >= 0} {
    # Look for slack lines
    if {[regexp {slack:\s*(-?[0-9]+\.[0-9]+)} $line match slack_val]} {
        lappend setup_slacks $slack_val
    }
}
close $file

# Calculate worst setup slack and total negative setup slack
set worst_setup_slack [lindex $setup_slacks 0]
if {[llength $setup_slacks] > 0} {
    foreach slack $setup_slacks {
        if {$slack < $worst_setup_slack} {
            set worst_setup_slack $slack
        }
        if {$slack < 0} {
            set total_neg_setup_slack [expr {$total_neg_setup_slack + $slack}]
            incr setup_violating_count
        }
    }
}

# 5. Parse hold timing
set worst_hold_slack 0.0
set file [open outputs/hold_timing.txt r]
while {[gets $file line] >= 0} {
    if {[regexp {slack:\s*(-?[0-9]+\.[0-9]+)} $line match slack_val]} {
        if {$worst_hold_slack == 0 && $slack_val != 0} {
            set worst_hold_slack $slack_val
        }
        if {$slack_val < $worst_hold_slack} {
            set worst_hold_slack $slack_val
        }
    }
}
close $file

# If no hold slacks were found (unlikely), default to 0
if {$worst_hold_slack == 0 && $setup_slacks eq ""} {
    set worst_hold_slack 0
}

# 6. Write summary
set summary_file [open outputs/signoff_summary.txt w]
puts $summary_file [format "worst_setup_slack %.4f" $worst_setup_slack]
puts $summary_file [format "total_negative_setup_slack %.4f" $total_neg_setup_slack]
puts $summary_file [format "worst_hold_slack %.4f" $worst_hold_slack]
puts $summary_file [format "setup_violating_endpoints %d" $setup_violating_count]
close $summary_file
